            typ, _ = peek()
            if typ == '+':
                consume()
                val = val + parse_term()
            elif typ == '-':
                consume()
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            typ, _ = peek()
            if typ == '*':
                consume()
                val = val * parse_factor()
            elif typ == '/':
                consume()
                rhs = parse_factor()
                sign = -1 if (val < 0) != (rhs < 0) else 1
                val = sign * (abs(val) // abs(rhs))
            else:
                break
        return val

    def parse_factor():
        neg = False
        while True:
            typ, _ = peek()
            if typ == '-':
                consume()
                neg = not neg
            elif typ == '+':
                consume()
            else:
                break
        val = parse_primary()
        return -val if neg else val

    def parse_primary():
        typ, v = peek()
        if typ == 'NUM':
            consume()
            return v
        elif typ == '(':
            consume()
            val = parse_expr()
            typ2, _ = peek()
            if typ2 != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return val
        else:
            raise ValueError(f"Unexpected token: {typ}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

